export function catalogCategories(pages){return [...new Set(pages.map(p=>p.category||'Bez kategorii'))].sort((a,b)=>a.localeCompare(b,'pl'));}
export function filterCatalog(pages,category='all',sort='folio'){const result=pages.filter(p=>category==='all'||(p.category||'Bez kategorii')===category);return [...result].sort((a,b)=>sort==='category'?((a.category||'').localeCompare(b.category||'','pl')||a.scan_number-b.scan_number):a.scan_number-b.scan_number);}
export function splitRanges(cut,axis,count){if(!['x','y','z'].includes(axis)||![2,3,4].includes(count))throw Error('Invalid split');const min=cut[axis+'Min'],max=cut[axis+'Max'],step=(max-min)/count;if(step<.019)throw Error('Fragment jest zbyt wąski do dalszego podziału.');return Array.from({length:count},(_,i)=>({...cut,[axis+'Min']:min+i*step,[axis+'Max']:min+(i+1)*step}));}
